package com.socialblog.interaction.application;import com.socialblog.interaction.api.ApiException;import com.socialblog.interaction.domain.*;import com.socialblog.interaction.repository.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;import java.nio.charset.StandardCharsets;
@Service public class InteractionService{public record State(TargetType targetType,UUID targetId,long count,boolean likedByCurrentUser,String reactionType){}private final InteractionRepository interactions;private final TargetProjectionRepository targets;private final OutboxEventRepository outbox;private final DomainEventFactory events;public InteractionService(InteractionRepository i,TargetProjectionRepository t,OutboxEventRepository o,DomainEventFactory e){interactions=i;targets=t;outbox=o;events=e;}@Transactional public State like(UUID actor,TargetType type,UUID target,String reactionType){TargetProjection projection=requireTarget(type,target);interactions.findByActorIdAndTargetTypeAndTargetId(actor,type,target).ifPresentOrElse(x->{if(!x.getReactionType().equals(reactionType)){x.setReactionType(reactionType);interactions.save(x);}},()->{Interaction x=interactions.save(new Interaction(actor,type,target,reactionType));outbox.save(events.created(x,projection.getOwnerId()));});return state(actor,type,target);}@Transactional public State likeMedia(UUID actor,String url,UUID articleId,String reactionType){UUID target=UUID.nameUUIDFromBytes(url.getBytes(StandardCharsets.UTF_8));TargetProjection articleProj=requireTarget(TargetType.ARTICLE,articleId);interactions.findByActorIdAndTargetTypeAndTargetId(actor,TargetType.MEDIA,target).ifPresentOrElse(x->{if(!x.getReactionType().equals(reactionType)){x.setReactionType(reactionType);interactions.save(x);}},()->{Interaction x=interactions.save(new Interaction(actor,TargetType.MEDIA,target,reactionType));outbox.save(events.created(x,articleProj.getOwnerId()));});return state(actor,TargetType.MEDIA,target);}@Transactional public State unlike(UUID actor,TargetType type,UUID target){interactions.findByActorIdAndTargetTypeAndTargetId(actor,type,target).ifPresent(x->{interactions.delete(x);outbox.save(events.removed(x));});return state(actor,type,target);}@Transactional public State unlikeMedia(UUID actor,String url){UUID target=UUID.nameUUIDFromBytes(url.getBytes(StandardCharsets.UTF_8));interactions.findByActorIdAndTargetTypeAndTargetId(actor,TargetType.MEDIA,target).ifPresent(x->{interactions.delete(x);outbox.save(events.removed(x));});return state(actor,TargetType.MEDIA,target);}@Transactional(readOnly=true)public State get(UUID actor,TargetType type,UUID target){Optional<Interaction> ix=actor!=null?interactions.findByActorIdAndTargetTypeAndTargetId(actor,type,target):Optional.empty();return new State(type,target,interactions.countByTargetTypeAndTargetId(type,target),ix.isPresent(),ix.map(Interaction::getReactionType).orElse(null));}@Transactional(readOnly=true)public State getMediaState(UUID actor,String url){UUID target=UUID.nameUUIDFromBytes(url.getBytes(StandardCharsets.UTF_8));return get(actor,TargetType.MEDIA,target);}@Transactional(readOnly=true)public org.springframework.data.domain.Page<Interaction> getLikers(TargetType type,UUID target,org.springframework.data.domain.Pageable pageable){return interactions.findByTargetTypeAndTargetId(type,target,pageable);}private State state(UUID actor,TargetType type,UUID target){interactions.flush();return get(actor,type,target);}private TargetProjection requireTarget(TargetType type,UUID id){return targets.findById(new TargetKey(type,id)).filter(TargetProjection::isActive).orElseThrow(()->new ApiException(HttpStatus.CONFLICT,"TARGET_NOT_AVAILABLE","Target does not exist or is unavailable"));}}
